content.helm.valuesObject:
{"alloy":{"configMap":{"content":"
otelcol.receiver.otlp "gateway" {
  http {
    endpoint = "0.0.0.0:4318"
    max_request_body_size = "64MiB"
  }

  output {
    traces = [otelcol.processor.batch.tempo.input]
  }
}

otelcol.processor.batch "tempo" {
  output {
    traces = [otelcol.exporter.otlphttp.tempo.input]
  }
}

otelcol.exporter.otlphttp "tempo" {
  client {
    endpoint = "http://tempo.tempo.svc.cluster.local:4318"
  }
}

otelcol.receiver.otlp "tailnet_metrics" {
  http {
    endpoint = "0.0.0.0:4319"
  }

  output {
    metrics = [otelcol.processor.filter.tailnet_metrics.input]
  }
}

otelcol.processor.filter "tailnet_metrics" {
  metrics {
    metric = [
      "not IsMatch(name, \"^(ai_usage_|ai_subscription_)\") and not (resource.attributes[\"service.name\"] == \"justin-principal-engineer\" and IsMatch(name, \"^(justin_reconcile_last_started_timestamp_seconds|justin_reconcile_last_success_timestamp_seconds|justin_stage_deadline_timestamp_seconds|justin_consecutive_failures|justin_queue_eligible|justin_open_pull_requests|justin_tasks|justin_oldest_wait_seconds|justin_task_transitions_total|justin_stage_elapsed_seconds_total|justin_stages_total|justin_reconciles_total|justin_codex_tokens_total|justin_passes_total)$\"))",
    ]
  }

  output {
    metrics = [otelcol.processor.batch.tailnet_metrics.input]
  }
}

otelcol.processor.batch "tailnet_metrics" {
  output {
    metrics = [otelcol.exporter.prometheus.tailnet.input]
  }
}

otelcol.exporter.prometheus "tailnet" {
  add_metric_suffixes  = false
  include_target_info  = false
  include_scope_labels = false
  forward_to           = [prometheus.remote_write.cluster.receiver]
}

prometheus.remote_write "cluster" {
  endpoint {
    url = "http://prometheus-kube-prometheus-prometheus.prometheus:9090/api/v1/write"
    authorization {
      type        = "Bearer"
      credentials = sys.env("PROMETHEUS_WRITE_TOKEN")
    }
  }
}
"},"extraEnv":[{"name":"PROMETHEUS_WRITE_TOKEN","valueFrom":{"secretKeyRef":{"key":"prometheus-write-token","name":"alloy-gateway-monitoring-api-auth"}}}],"extraPorts":[{"name":"otlp-http","port":4318,"protocol":"TCP","targetPort":4318},{"name":"otlp-metrics","port":4319,"protocol":"TCP","targetPort":4319}],"resources":{"requests":{"cpu":"100m","memory":"256Mi"}}},"controller":{"replicas":1,"type":"deployment"},"crds":{"create":false},"fullnameOverride":"alloy-gateway","rbac":{"create":false},"serviceAccount":{"automountServiceAccountToken":false},"serviceMonitor":{"additionalLabels":{"release":"prometheus"},"enabled":true}}
